package cn.workbench;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.stereotype.Component;import java.util.*;
@Component public class Jsons {private final ObjectMapper mapper;public Jsons(ObjectMapper m){mapper=m;}public String write(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}}public Map<String,Object> map(String s){try{return mapper.readValue(s,new TypeReference<LinkedHashMap<String,Object>>(){});}catch(Exception e){throw new IllegalStateException(e);}}public static int integer(Object o){return o instanceof Number n?n.intValue():Integer.parseInt(o.toString());}public static long number(Object o){return o instanceof Number n?n.longValue():Long.parseLong(o.toString());} }
